import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.createNumber to maximize branch and line coverage.
 */
public class NumberUtils_createNumber_TriageGen0Test {









    @Test
    public void testCreateNumber_IntegerTypes() {
        // Integer
        assertEquals(Integer.valueOf(123), NumberUtils.createNumber("123"));
        // Long
        assertEquals(Long.valueOf(123L), NumberUtils.createNumber("123L"));
        assertEquals(Long.valueOf(-123L), NumberUtils.createNumber("-123l"));
        // BigInteger
        String bigIntStr = "9223372036854775808"; // Long.MAX_VALUE + 1
        assertEquals(new BigInteger(bigIntStr), NumberUtils.createNumber(bigIntStr));
        assertEquals(new BigInteger(bigIntStr + "L"), NumberUtils.createNumber(bigIntStr + "L"));
    }
















}

