package org.apache.commons.lang.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for NumberUtils.createNumber to maximize branch and line coverage.
 */
public class NumberUtils_createNumber_TriageGen0Test {















    @Test
    public void testCreateNumber_InvalidExponents() {
        // expPos < decPos case: "1.2e" -> decPos=1, expPos=3 (if e is found)
        // The logic: int expPos = str.indexOf('e') + str.indexOf('E') + 1;
        // If 'e' is present, indexOf('e') is index, indexOf('E') is -1. 
        // So expPos = index + (-1) + 1 = index. 
        // If str = "1.e2", decPos=1, expPos=2. 2 < 1 is false.
        // To trigger expPos < decPos:
        // If str = "1e.2", decPos=2, expPos=1. 1 < 2 is true.
        try {
            NumberUtils.createNumber("1e.2");
            fail("Should have thrown NumberFormatException");
        } catch (NumberFormatException e) {
            assertTrue(e.getMessage().contains("is not a valid number"));
        }
    }










}

